339: // Index 0 = Red level, 1 = Amber level, 2 = Orange level
340: const CHOICE_THRESHOLDS: Record<string, [number, number, number]> = {
341:   Cognitive: [1.8, 2.2, 2.8],
342:   Emotional: [2, 2.5, 3],
343:   Moral: [2, 2.5, 3],
344:   Intrapersonal: [2, 2.5, 3],
345:   Spiritual: [2, 2.5, 3],
346:   Interpersonal: [2, 2.5, 3],
347: };
348: 
349: const HOLD_TARGETS: Record<string, number> = {
350:   Somatic: 4000,
351:   Willpower: 5000,
352: };
