356: async function runQuickCalibration(): Promise<Record<Line, Stage>> {
357:   const altitudes: Partial<Record<Line, Stage>> = {};
358:   const lines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
359: 
360:   banner('Quick Calibration');
361:   console.log(`  ${chalk.dim('A brief probe of each developmental line to set your starting altitudes.')}\n`);
362: 
363:   for (const line of lines) {
364:     let stage: Stage = 'Red';
365:     let confidence = 0.5;
366:     let trial: TrialResult;
367: 
368:     if (line === 'Somatic' || line === 'Willpower') {
369:       // ── Hold probe: measure timing accuracy ──
370:       const target = HOLD_TARGETS[line]!;
371:       const targetSec = (target / 1000).toFixed(1);
372: 
373:       console.log(`  ${chalk.bold.cyan(line + ':')} ${chalk.dim('Timing probe')}`);
374:       console.log(`  ${chalk.dim('Press Enter when you think ' + targetSec + ' seconds have passed.')}\n`);
375: 
376:       const startTime = Date.now();
377:       const answer = await clackText({ message: `Press Enter after ~${targetSec}s...`, defaultValue: '' });
378:       if (typeof answer === 'symbol') { altitudes[line] = 'Red'; continue; }
379:       const elapsed = Date.now() - startTime;
380: 
381:       const accuracy = Math.max(0, 1 - Math.abs(elapsed - target) / target);
382: 
383:       let threshold: number;
384:       if (line === 'Somatic') {
385:         // Inverted: lower RT = higher stage (range 200-900)
386:         threshold = 900 - accuracy * 700;
387:       } else {
388:         // Standard: higher = better (range 1-12)
389:         threshold = 1 + accuracy * 11;
390:       }
391: 
392:       stage = thresholdToStage(line, threshold);
393: 
394:       trial = {
395:         taskId: `cal-${line.toLowerCase()}`,
396:         timestamp: Date.now(),
397:         dimensions: { accuracy, response_time: accuracy },
398:         rawResponse: elapsed,
399:         durationMs: elapsed,
400:       };
401: 
402:       confidence = computeConfidence([trial], 0.5);
403: 
404:     } else {
405:       // ── LLM dialogue probe: multiple choice ──
406:       const probe = CALIBRATION_PROMPTS[line];
407:       if (!probe) { altitudes[line] = 'Red'; continue; }
408: 
409:       console.log(`  ${chalk.bold.cyan(line + ':')}`);
410:       console.log(`  ${chalk.dim(probe.prompt)}\n`);
411: 
412:       const choice = await select({
413:         message: `How would you approach this?`,
414:         options: probe.options.map((opt) => ({ value: opt, label: opt })),
415:       });
416: 
417:       if (typeof choice === 'symbol') { altitudes[line] = 'Red'; continue; }
418: 
419:       const choiceIdx = probe.options.indexOf(choice as string);
420:       const idx = choiceIdx >= 0 ? choiceIdx : 0;
421: 
422:       const thresholds = CHOICE_THRESHOLDS[line]!;
423:       const threshold = thresholds[Math.min(idx, 2)];
424: 
425:       stage = thresholdToStage(line, threshold);
426: 
427:       const depthScores = [0.3, 0.6, 0.85];
428:       const coherenceScores = [0.4, 0.7, 0.9];
429: 
430:       trial = {
431:         taskId: `cal-${line.toLowerCase()}`,
432:         timestamp: Date.now(),
433:         dimensions: { depth: depthScores[idx], coherence: coherenceScores[idx] },
434:         rawResponse: idx,
435:         durationMs: 0,
436:       };
437: 
438:       confidence = computeConfidence([trial], 0.5);
439:     }
440: 
441:     altitudes[line] = stage;
442: 
443:     const stageIdx = CAL_STAGES.indexOf(stage as typeof CAL_STAGES[number]);
444:     const color = stageColor(stage);
445:     const bar = '■'.repeat(stageIdx + 1) + '○'.repeat(7 - stageIdx);
446:     console.log(`  ${line.padEnd(14)} ${bar} ${color(stage)} ${chalk.dim('(confidence: ' + confidence.toFixed(2) + ')')}\n`);
447:   }
448: 
449:   console.log(`\n  ${chalk.bold('Calibration complete:')}`);
450:   for (const line of lines) {
451:     const s = altitudes[line] ?? 'Red';
452:     const color = stageColor(s);
453:     console.log(`    ${line.padEnd(14)} ${color(s)}`);
454:   }
455:   console.log('');
456: 
457:   return altitudes as Record<Line, Stage>;
458: }
