709: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
710: async function runAgenticEncounter(
711:   encounter: ScheduledEncounter,
712:   sig: Significator,
713:   world: WorldState,
714:   history: ConsequenceRecord[],
715:   responsesPool?: number[],
716:   consecutivePasses?: Map<string, number>,
717: ): Promise<{
718:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
719:   response: PlayerResponse;
720:   narrativeSummary: string;
721: }> {
722:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
723:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
724: 
725:   // If --line/--stage/--modality forcing is active, override the encounter
726:   let forcedEncounter = encounter;
727:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
728:     const forcedLine = FORCE_LINE ?? encLine;
729:     const forcedStage = FORCE_STAGE ?? encStage;
730:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
731:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
732:     if (forcedModule) {
733:       forcedEncounter = {
734:         ...encounter,
735:         moduleRef: `${forcedLine}:${forcedStage}`,
736:         modality: forcedModality,
737:         targetLines: [forcedLine],
738:         stage: forcedStage,
739:       };
740:     }
741:   }
742: 
743:   const uiHandler: AgenticUIHandler = {
744:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
745:       const answers: UserAnswer[] = [];
746: 
747:       for (const q of params.questions) {
748:         if (!JSON_MODE) {
749:           const mod = forcedEncounter.modality;
750:           let modHeader = '';
751: 
752:           switch (mod) {
753:             case 'Deterministic':
754:               modHeader = `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
755:               break;
756:             case 'LanguageReflective':
757:               modHeader = `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
758:               break;
759:             case 'ScenarioChoice':
760:               modHeader = `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
761:               break;
762:             case 'Embodied':
763:               modHeader = `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
764:               break;
765:             case 'Strategic':
766:               modHeader = `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
767:               break;
768:             case 'SocialCooperative':
769:               modHeader = `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
770:               break;
771:             case 'ImmersiveRPG':
772:               modHeader = `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
773:               break;
774:             default:
775:               modHeader = `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
776:           }
777: 
778:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
779:           console.log(`  ${chalk.bold(q.question)}`);
780:           if (q.options?.length) {
781:             for (let i = 0; i < q.options.length; i++) {
782:               const opt = q.options[i];
783:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
784:             }
785:           }
786:         }
787: 
788:         emitEvent('ask_user', {
789:           header: q.header,
790:           question: q.question,
791:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
792:           allowWriteIn: q.allowWriteIn,
793:         });
794: 
795:         if (HEADLESS) {
796:           // Use forced responses pool if provided (one index per question, consumed sequentially)
797:           let selectedIdx: number;
798:           if (responsesPool && responsesPool.length > 0) {
799:             const forcedIdx = responsesPool.shift()!;
800:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
801:               selectedIdx = forcedIdx - 1;
802:             } else {
803:               selectedIdx = 0;
804:             }
805:           } else {
806:             // Vary selection to probe different shadow patterns:
807:             // Cycle through options to ensure shadow detection has varied input
808:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
809:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
810:           }
811:           const selectedOpt = q.options?.[selectedIdx];
812:           const selectedLabel = selectedOpt?.label ?? '';
813: 
814:           // Shadow keyword injection for testing — randomly inject (10% chance)
815:           // to allow MOST encounters to pass and demonstrate altitude shifts.
816:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
817:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
818:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
819:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
820: 
821:           if (writeInShadow) {
822:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
823:           } else {
824:             answers.push({ selectedLabels: [selectedLabel] });
825:           }
826:         } else {
827:           const promptText = q.multiSelect
828:             ? '\n  Select (comma-separated): '
829:             : '\n  Select: ';
830:           const answer = await ask(promptText);
831:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
832:           const selectedLabels = selections
833:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
834:             .map(n => q.options![n - 1]!.label);
835: 
836:           // Determine if input is a simple numeric choice from the options
837:           let isSimpleNumericChoice = false;
838:           if (q.options?.length && answer.trim()) {
839:             const parts = answer.split(',').map(s => s.trim());
840:             isSimpleNumericChoice = parts.every(part => {
841:               const num = parseInt(part, 10);
842:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
843:             });
844:           }
845: 
846:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
