848:             if (!isSimpleNumericChoice && answer.trim()) {
849:               answers.push({ selectedLabels, writeInValue: answer.trim() });
850:             } else {
851:               answers.push({ selectedLabels });
852:             }
853:           } else {
854:             answers.push({ selectedLabels });
855:           }
856:         }
857:       }
858: 
859:       return { answers };
860:     }
