1431: // ── Ollama auto-detect ──────────────────────────────────────────
1432: async function detectOllama(): Promise<{ running: boolean; models: string[] }> {
1433:   try {
1434:     const controller = new AbortController();
1435:     const timeout = setTimeout(() => controller.abort(), 3000);
1436:     const res = await fetch('http://localhost:11434/api/tags', { signal: controller.signal });
1437:     clearTimeout(timeout);
1438:     if (!res.ok) return { running: false, models: [] };
1439:     const data = (await res.json()) as { models?: { name: string }[] };
1440:     const models = (data.models ?? []).map(m => m.name.split(':')[0] ?? m.name);
1441:     return { running: true, models: [...new Set(models)] };
1442:   } catch {
1443:     return { running: false, models: [] };
1444:   }
1445: }
